class Solution {
  public List<List<String>> wordSquares(String[] words) {
    String[] w = words.clone();
    java.util.Arrays.sort(w);
    List<List<String>> res = new ArrayList<>();
    int n = w.length;
    for (int a = 0; a < n; a++) {
      for (int b = 0; b < n; b++) {
        if (b == a || w[a].charAt(0) != w[b].charAt(0)) continue;
        for (int c = 0; c < n; c++) {
          if (c == a || c == b || w[a].charAt(3) != w[c].charAt(0)) continue;
          for (int d = 0; d < n; d++) {
            if (d == a || d == b || d == c) continue;
            if (w[d].charAt(0) == w[b].charAt(3) && w[d].charAt(3) == w[c].charAt(3)) {
              res.add(java.util.Arrays.asList(w[a], w[b], w[c], w[d]));
            }
          }
        }
      }
    }
    return res;
  }
}
